import React, { useState } from 'react';

function Login({ onLogin }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = () => {
    if (!username || !password) {
      alert('请输入用户名和密码');
      return;
    }

    setIsLoading(true);
    setTimeout(() => {
      onLogin({
        username,
        password,
        needProfile: true
      });
      setIsLoading(false);
    }, 1000);
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      display: 'flex', 
      alignItems: 'center', 
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
    }}>
      <div style={{
        background: 'white',
        padding: '50px 60px',
        borderRadius: '24px',
        boxShadow: '0 20px 60px rgba(0,0,0,0.2)',
        width: '100%',
        maxWidth: '450px'
      }}>
        <div style={{ textAlign: 'center', marginBottom: '40px' }}>
          <div style={{ fontSize: '72px', marginBottom: '20px' }}>👨‍⚕️</div>
          <h1 style={{ fontSize: '32px', fontWeight: 'bold', color: '#667eea' }}>AI智能药剂师</h1>
          <p style={{ fontSize: '18px', color: '#666', marginTop: '8px' }}>您身边贴心的用药安全小助手</p>
        </div>

        <div style={{ marginBottom: '24px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>用户名</label>
          <input
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="请输入用户名"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <div style={{ marginBottom: '32px' }}>
          <label style={{ 
            fontSize: '20px', 
            fontWeight: '600', 
            marginBottom: '10px', 
            display: 'block',
            color: '#444'
          }}>密码</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="请输入密码"
            style={{
              width: '100%',
              padding: '16px 20px',
              fontSize: '20px',
              border: '3px solid #ddd',
              borderRadius: '12px',
              outline: 'none',
              transition: 'all 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#ddd'}
          />
        </div>

        <button
          onClick={handleLogin}
          disabled={isLoading}
          style={{
            width: '100%',
            padding: '20px',
            fontSize: '22px',
            fontWeight: 'bold',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            cursor: isLoading ? 'not-allowed' : 'pointer',
            boxShadow: '0 8px 20px rgba(102, 126, 234, 0.3)',
            transition: 'all 0.3s ease'
          }}
        >
          {isLoading ? (
            <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px' }}>
              <svg className="animate-spin" style={{ width: '24px', height: '24px' }} viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              登录中...
            </span>
          ) : (
            '登录'
          )}
        </button>

        <div style={{ textAlign: 'center', marginTop: '24px' }}>
          <p style={{ fontSize: '16px', color: '#888' }}>
            测试账号：admin / 123456
          </p>
        </div>
      </div>
    </div>
  );
}

export default Login;
